using EEMS.Modules.Reporting.Infrastructure;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;namespace EEMS.Modules.Reporting;public static class ReportingModule{public static IServiceCollection AddReportingModule(this IServiceCollection s,IConfiguration c){var x=c.GetConnectionString("EemsDatabase");if(string.IsNullOrWhiteSpace(x))throw new InvalidOperationException("ConnectionStrings:EemsDatabase is required.");s.AddDbContext<ReportingDbContext>(o=>o.UseNpgsql(x));return s;}}
